347	    /** The sheet's claims, newest first. */
348	    @Transactional(readOnly = true)
349	    public List<Claim> list(String sheetId) {
350	        sheets.today(sheetId); // the sheet must exist
351	        return claims.findBySheetIdOrderByIdDesc(sheetId);
352	    }
353	
354	    /** Add a claim for a person; a claim without a date is dated the sheet's today. One dated in a closed period
355	     * is refused, and so is a correction that does not name a settled claim of the same person. */
356	    @Transactional
357	    public Claim add(String user, String sheetId, Long personId, BigDecimal amount, LocalDate date, String note,
358	            String corrects) {
359	        LocalDate today = sheets.today(sheetId);
360	        Person person = requirePerson(sheetId, personId);
361	        requireNotRetired(person, date != null ? date : today);
362	        requireOpenPeriod(sheetId, date != null ? date : today);
363	        String corrected = correctedBy(sheetId, personId, amount, corrects);
364	        Snapshot before = rollup.snapshot(sheetId);
365	        Claim fresh = new Claim(sheetId, personId, amount, date != null ? date : today, noteOf(note));
366	        fresh.setCorrects(corrected);
367	        Claim claim = claims.saveAndFlush(fresh);
368	        audit.recordOnCommit(entry("CLAIM_ADDED", user, person, claim));
369	        rollup.recordChanges(user, sheetId, before);
370	        return claim;
371	    }
372	
373	    /** Edit a claim; only a draft can be edited (an open claim is voided and added again instead), and one dated
374	     * in a closed period, or that would be, is refused, as is a correction that does not name a settled claim of
375	     * the same person. */
376	    @Transactional
377	    public Claim update(String user, String sheetId, Long id, BigDecimal amount, LocalDate date, String note,
378	            String corrects) {
379	        LocalDate today = sheets.today(sheetId);
380	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
381	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
382	        if (claim.getStatus() != ClaimStatus.DRAFT) {
383	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft claim can be edited.");
384	        }
385	        requireOpenPeriod(sheetId, claim.getDate());
386	        requireOpenPeriod(sheetId, date != null ? date : today);
387	        requireNotRetired(requirePerson(sheetId, claim.getPersonId()), date != null ? date : today);
388	        String corrected = correctedBy(sheetId, claim.getPersonId(), amount, corrects);
389	        Snapshot before = rollup.snapshot(sheetId);
390	        claim.setAmount(amount);
391	        claim.setCorrects(corrected);
392	        claim.setDate(date != null ? date : today);
393	        claim.setNote(noteOf(note));
394	        claims.flush();
395	        audit.recordOnCommit(entry("CLAIM_EDITED", user, requirePerson(sheetId, claim.getPersonId()), claim));
396	        rollup.recordChanges(user, sheetId, before);
397	        return claim;
398	    }
