400	    /** Move a claim to another status; a change its status does not allow, or of a claim dated in a closed
401	     * period, is refused; so is a settle by a clerk of a claim whose due is above the clerk limit. */
402	    @Transactional
403	    public Claim changeStatus(String user, String sheetId, Long id, ClaimStatus next) {
404	        sheets.today(sheetId); // the sheet must exist
405	        // Locking the sheet before taking the number opens claims one at a time; a refused open rolls back
406	        // and gives the number back.
407	        if (next == ClaimStatus.OPEN) {
408	            sheets.lock(sheetId);
409	        }
410	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
411	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
412	        String number = next == ClaimStatus.OPEN ? nextNumber(sheetId, claim) : null;
413	        requireOpenPeriod(sheetId, claim.getDate());
414	        if (!claim.getStatus().canBecome(next)) {
415	            throw new ResponseStatusException(HttpStatus.CONFLICT,
416	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
417	        }
418	        // Four eyes: whoever opened a claim cannot also settle it.
419	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
420	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it.");
421	        }
422	        Person person = requirePerson(sheetId, claim.getPersonId());
423	        // A clerk settles only a claim whose due is within the sheet's clerk limit.
424	        if (next == ClaimStatus.SETTLED) {
425	            settings.requireMaySettle(sheetId, user, rollup.dueOf(claim, person));
426	        }
427	        Snapshot before = rollup.snapshot(sheetId);
428	        BigDecimal due = rollup.dueOf(claim, person);
429	        claim.setStatus(next);
430	        if (next == ClaimStatus.OPEN) {
431	            claim.setNumber(number);
432	            claim.setOpenedBy(user);
433	        }
434	        // A voided claim's line carries the number it had.
435	        String entry = entry(EVENTS.get(next), user, person, claim);
436	        if (next == ClaimStatus.SETTLED) {
437	            // Settling fixes the due at the figure the claim has: the one its last statement bound it to, else
438	            // the rate its grade has on its date; with no figure it stays live. The late charge it has (taken
439	            // while it is still OPEN) is frozen in.
440	            claim.setSettledDue(due);
441	            entry += " due=" + (claim.getSettledDue() != null ? claim.getSettledDue().toPlainString() : "n/a");
442	        }
443	        claims.flush();
444	        audit.recordOnCommit(entry);
445	        rollup.recordChanges(user, sheetId, before);
446	        return claim;
447	    }
448	
449	    /** What opening claims together did: how many were opened and refused, and the opened claims. */
450	    public record OpenedAll(int opened, int refused, List<Claim> claims) {}
451	
452	    /** Open the given claims of the sheet one at a time, in list order: people in the order they were added,
453	     * each one's claims newest first. Each is opened, and numbered, as {@link #changeStatus} would open it on its
454	     * own; one that cannot be opened (or is not on the sheet) is refused and left as it is. */
455	    public OpenedAll openAll(String user, String sheetId, List<Long> ids) {
456	        Set<Long> wanted = new HashSet<>(ids);
457	        List<Claim> chosen = transaction.execute(status -> {
458	            sheets.today(sheetId); // the sheet must exist
459	            Map<Long, Integer> personOrder = new HashMap<>();
460	            for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
461	                personOrder.put(person.getId(), personOrder.size());
462	            }
463	            return claims.findBySheetIdOrderByIdDesc(sheetId).stream()
464	                    .filter(c -> wanted.contains(c.getId()))
465	                    .sorted(Comparator.comparing((Claim c) -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE)))
466	                    .toList();
467	        });
468	        List<Claim> opened = new ArrayList<>();
469	        for (Claim claim : chosen) {
470	            try {
471	                opened.add(transaction.execute(status -> changeStatus(user, sheetId, claim.getId(), ClaimStatus.OPEN)));
472	            } catch (ResponseStatusException refused) {
473	                // Left as it is: its transaction rolled back, writing nothing.
474	            }
475	        }
476	        return new OpenedAll(opened.size(), wanted.size() - opened.size(), opened);
477	    }
478	
479	    /** The sequence a claim in no period is numbered in, with period numbering. */
480	    private static final String NO_PERIOD = "X";
481	
482	    private static final Map<ClaimStatus, String> EVENTS = Map.of(
483	            ClaimStatus.OPEN, "CLAIM_OPENED",
484	            ClaimStatus.SETTLED, "CLAIM_SETTLED",
485	            ClaimStatus.VOID, "CLAIM_VOIDED");
486	
487	    /** The figure a claim has now: what it was settled at, else what its person's last statement bound it to,
488	     * else what is due at the rate of the grade its person has on its date; none when that is n/a. */
489	    public BigDecimal figureOf(Claim claim, Person person) {
490	        return rollup.figureOf(claim, person);
491	    }
492	
493	    /** The number a claim opened now takes: the sheet's next number or, with period numbering in force, the next
494	     * in its period's own sequence, <period name>-<n>, or X-<n> for a claim in no period. */
495	    private String nextNumber(String sheetId, Claim claim) {
496	        if (!sheets.numbersByPeriod(sheetId)) {
497	            return String.valueOf(sheets.nextClaimNumber(sheetId));
498	        }
499	        String prefix = periods.periodOf(sheetId, claim.getDate()).map(Period::getName).orElse(NO_PERIOD) + "-";
500	        int last = 0;
501	        for (Claim other : claims.findBySheetIdOrderByIdDesc(sheetId)) {
502	            String number = other.getNumber();
503	            if (number != null && number.startsWith(prefix)) {
504	                String rest = number.substring(prefix.length());
505	                if (rest.matches("\\d{1,9}")) {
506	                    last = Math.max(last, Integer.parseInt(rest));
507	                }
508	            }
509	        }
510	        return prefix + (last + 1);
511	    }
512	
513	    /** The number a claim of this amount corrects: none unless the amount is negative, when it must name a
514	     * SETTLED claim of the same person, or the claim is refused. */
515	    private String correctedBy(String sheetId, Long personId, BigDecimal amount, String corrects) {
516	        if (amount.signum() >= 0) {
517	            return null;
518	        }
519	        String named = corrects == null ? null : corrects.trim();
520	        boolean settled = named != null && claims.findBySheetIdAndPersonId(sheetId, personId).stream()
521	                .anyMatch(c -> named.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
522	        if (!settled) {
523	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
524	                    "A correction must name a settled claim of the same person.");
525	        }
526	        return named;
527	    }
528	
529	    /** Refuse a change to a claim dated in a closed period. Locks the sheet first, so a period cannot close
530	     * while the change is made. */
531	    private void requireOpenPeriod(String sheetId, LocalDate date) {
532	        sheets.lock(sheetId);
533	        periods.requireOpen(sheetId, date);
534	    }
535	
536	    /** Refuse a claim dated after its person's retirement. */
537	    private static void requireNotRetired(Person person, LocalDate date) {
538	        if (person.retiredOn(date)) {
539	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
540	                    person.getName() + " is retired from " + person.getRetiredFrom() + ".");
541	        }
542	    }
543	
544	    private Person requirePerson(String sheetId, Long personId) {
545	        return people.findByIdAndSheetId(personId, sheetId)
546	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
547	    }
548	
549	    /** The amount is written as the screen shows it, with two decimals; the date as yyyy-mm-dd; a
550	     * claim with a number ends with it. */
551	    private static String entry(String event, String user, Person person, Claim claim) {
552	        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
553	                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
554	                + (claim.getNumber() != null ? " number=" + claim.getNumber() : "");
555	    }
556	
557	    private static String noteOf(String note) {
558	        return note == null ? "" : note.trim();
559	    }
560	}
561	package net.officefloor.hq.app.claim;
562	
563	/** A claim's status. Only OPEN and SETTLED claims count toward what is claimed and due. */
564	public enum ClaimStatus {
565	    DRAFT, OPEN, SETTLED, VOID;
566	
567	    /** Whether a claim in this status may move to the given status. */
568	    public boolean canBecome(ClaimStatus next) {
569	        return switch (next) {
570	            case OPEN -> this == DRAFT;
571	            case SETTLED -> this == OPEN;
572	            case VOID -> this == DRAFT || this == OPEN;
573	            case DRAFT -> false;
574	        };
575	    }
576	}
