599	
600	@Service
601	public class StatementService {
602	
603	    /** What a person's statements come to: how many, and the last one (none before the first). */
604	    public record Summary(int count, Statement last) {}
605	
606	    private final StatementRepository statements;
607	    private final ClaimRepository claims;
608	    private final ClaimService claimService;
609	    private final PersonRepository people;
610	    private final SheetService sheets;
611	    private final RollupService rollup;
612	    private final Audit audit;
613	
614	    public StatementService(StatementRepository statements, ClaimRepository claims, ClaimService claimService,
615	            PersonRepository people, SheetService sheets, RollupService rollup, Audit audit) {
616	        this.statements = statements;
617	        this.claims = claims;
618	        this.claimService = claimService;
619	        this.people = people;
620	        this.sheets = sheets;
621	        this.rollup = rollup;
622	        this.audit = audit;
623	    }
624	
625	    /** Each person's statements on the sheet, by person id. */
626	    @Transactional(readOnly = true)
627	    public Map<Long, Summary> summaries(String sheetId) {
628	        Map<Long, Summary> by = new HashMap<>();
629	        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
630	            Summary was = by.get(s.getPersonId());
631	            by.put(s.getPersonId(), new Summary(was == null ? 1 : was.count() + 1, s));
632	        }
633	        return by;
634	    }
635	
636	    /**
637	     * Take a statement for a person: record their due-total now, late charges included, and bind each of their
638	     * claims that counts (a held person's OPEN ones do not) to the figure it has now (never its late charge, which keeps following the sheet's
639	     * today); a claim of theirs that does not count is left unbound.
640	     */
641	    @Transactional
642	    public Person take(String user, String sheetId, Long personId) {
643	        LocalDate today = sheets.today(sheetId);
644	        Person person = people.findByIdAndSheetId(personId, sheetId)
645	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
646	        Snapshot before = rollup.snapshot(sheetId);
647	        BigDecimal total = BigDecimal.ZERO.setScale(2);
648	        boolean fixed = false;
649	        List<Claim> counted = new ArrayList<>();
650	        for (Claim claim : claims.findBySheetIdAndPersonId(sheetId, personId)) {
651	            if (!counts(claim, person)) {
652	                claim.unbind();
653	                continue;
654	            }
655	            BigDecimal figure = claimService.figureOf(claim, person);
656	            BigDecimal due = rollup.dueOf(claim, person);
657	            fixed |= RollupService.keepsFigure(claim);
658	            claim.bind(figure);
659	            counted.add(claim);
660	            if (due != null) {
661	                total = total.add(due);
662	            }
663	        }
664	        // Like the screen: with no rate in force today and no claim keeping a figure, the due-total is n/a.
665	        boolean rated = rollup.rated(person, counted, today);
666	        BigDecimal dueTotal = rated || fixed ? total : null;
667	        claims.flush();
668	        statements.saveAndFlush(new Statement(sheetId, personId, today, user, dueTotal, counted.size()));
669	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
670	                + " due-total=" + (dueTotal != null ? dueTotal.toPlainString() : "n/a")
671	                + " claims=" + counted.size());
672	        rollup.recordChanges(user, sheetId, before);
673	        return person;
674	    }
675	
676	    /** Only OPEN and SETTLED claims count toward what is claimed and due; a held person's OPEN ones do not. */
677	    private static boolean counts(Claim claim, Person person) {
678	        return (claim.getStatus() == ClaimStatus.OPEN && !person.isHeld())
679	                || claim.getStatus() == ClaimStatus.SETTLED;
680	    }
681	}
