264	     * A statement never binds it: it follows the sheet's today. A correction has none.
265	     */
266	    private static BigDecimal lateCharge(Claim claim, BigDecimal figure, Lateness late, RoundingMode rounding) {
267	        if (claim.getStatus() != ClaimStatus.OPEN || late.today() == null || claim.isCorrection()) {
268	            return BigDecimal.ZERO.setScale(2);
269	        }
270	        long overdueDays = ChronoUnit.DAYS.between(claim.getDate().plusDays(late.terms()), late.today());
271	        long periods = overdueDays > 0 ? overdueDays / LATE_PERIOD_DAYS : 0;
