391	 * when there is no rate). An overdue claim's due adds its late charge to its figure. Live figures round by the
392	 * date `roundsBy` (see {@link roundsBy}). */
393	export function claimDue(
394	  claim: Claim,
395	  rates: readonly Rate[],
396	  grade: Grade | undefined,
397	  floor: string,
398	  late: Lateness,
399	  roundsBy: string = claim.date,
400	): string {
401	  if (claim.due !== null) return claim.due;
402	  const halfUp = roundsHalfUp(roundsBy, late);
403	  const figure = claim.stated
