425	function timesPct(pct: string, times: number): string {
426	  const [whole, frac = ''] = pct.split('.');
427	  const hundredths = (BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0'))) * BigInt(times);
428	  return `${hundredths / 100n}.${String(hundredths % 100n).padStart(2, '0')}`;
