435	}
436	
437	/** The date a claim is due by: its date plus the sheet's terms in days (yyyy-mm-dd). */
438	export function dueBy(claim: Claim, terms: number): string {
439	  const [y, m, d] = claim.date.split('-').map(Number);
440	  return new Date(Date.UTC(y, m - 1, d + terms)).toISOString().slice(0, 10);
441	}
442	
443	/** Whether a claim is overdue: it is OPEN and its due-by is before the sheet's today. */
444	export function isOverdue(claim: Claim, terms: number, today: string | null): boolean {
445	  return claim.status === 'OPEN' && today !== null && dueBy(claim, terms) < today;
446	}
447	
448	export interface ClaimForm {
449	  amount: string;
450	  /** Null for the sheet's today. */
451	  date: string | null;
452	  note: string;
453	  /** The number of the settled claim a correction corrects; null when none is named. */
454	  corrects: string | null;
455	}
456	
457	/** What opening claims together did: how many were opened and refused, and the opened claims. */
458	export interface OpenedAll {
459	  opened: number;
460	  refused: number;
461	  claims: Claim[];
462	}
463	
464	/** The sum of claim amounts with two decimals, added up in cents so no rounding creeps in. */
465	export function sumAmounts(amounts: string[]): string {
466	  return fromHundredths(amounts.reduce((sum, a) => sum + hundredths(a), 0n));
467	}
468	
469	// The claims people make on the active sheet, read and changed through the server.
470	@Injectable({ providedIn: 'root' })
471	export class ClaimsApi {
472	  private readonly http = inject(HttpClient);
473	  private readonly session = inject(Session);
474	
475	  list(sheetId: string): Observable<Claim[]> {
476	    return this.http.get<Claim[]>(`${this.url(sheetId)}/claims`, { headers: this.headers() });
477	  }
478	
479	  add(sheetId: string, personId: number, form: ClaimForm): Observable<Claim> {
480	    return this.http.post<Claim>(`${this.url(sheetId)}/people/${personId}/claims`, form, {
481	      headers: this.headers(),
482	    });
483	  }
484	
485	  update(sheetId: string, id: number, form: ClaimForm): Observable<Claim> {
486	    return this.http.put<Claim>(`${this.url(sheetId)}/claims/${id}`, form, { headers: this.headers() });
487	  }
488	
489	  changeStatus(sheetId: string, id: number, action: ClaimAction): Observable<Claim> {
490	    return this.http.post<Claim>(`${this.url(sheetId)}/claims/${id}/${action}`, null, { headers: this.headers() });
491	  }
492	
493	  /** Open the claims together; each that cannot be opened is refused and left as it is. */
494	  openAll(sheetId: string, ids: number[]): Observable<OpenedAll> {
495	    return this.http.post<OpenedAll>(`${this.url(sheetId)}/claims/open`, { ids }, { headers: this.headers() });
496	  }
497	
498	  private url(sheetId: string): string {
499	    return `/api/sheets/${encodeURIComponent(sheetId)}`;
500	  }
501	
502	  private headers(): Record<string, string> {
503	    return { 'X-User': this.session.user() ?? '' };
504	  }
505	}
506	import { HttpErrorResponse } from '@angular/common/http';
507	import { Component, computed, effect, inject, input, output, signal, untracked } from '@angular/core';
508	import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
509	import { Session } from '../../core/session';
510	import { Rate } from '../rates/rates-api';
511	import { GradeFrom, gradeOn } from '../people/people-api';
512	import { Period, periodOf } from '../periods/periods-api';
513	import { SheetFloor } from '../settings/sheet-floor';
514	import { SheetLatePct } from '../settings/sheet-late-pct';
515	import { SheetPolicyDate } from '../settings/sheet-policy-date';
516	import { SheetTerms } from '../settings/sheet-terms';
517	import { Claim, ClaimAction, ClaimsApi, Lateness, claimDue, dueBy, isOverdue, roundsBy } from './claims-api';
518	
519	const AMOUNT = /^-?\d{1,10}(\.\d{1,2})?$/;
520	/** A claim's number: the sheet-wide one, or a period's, <period name>-<n> (X-<n> in no period). */
521	const NUMBER = /^\S{1,255}$/;
522	
523	// One person's claims, newest first, and the one form that adds a claim for them or, once a
524	// claim's editor is opened, saves changes to it.
525	@Component({
526	  selector: 'app-claims',
527	  imports: [ReactiveFormsModule],
528	  template: `
529	    <form [formGroup]="form" (ngSubmit)="submit()" data-testid="claim-form">
530	      <label [for]="'claim-form-amount-' + personId()">Amount</label>
531	      <input
532	        [id]="'claim-form-amount-' + personId()"
533	        data-testid="claim-form-amount"
534	        inputmode="decimal"
535	        formControlName="amount"
536	      />
537	      <label [for]="'claim-form-date-' + personId()">Date</label>
538	      <input [id]="'claim-form-date-' + personId()" type="date" data-testid="claim-form-date" formControlName="date" />
539	      <label [for]="'claim-form-note-' + personId()">Note</label>
540	      <input [id]="'claim-form-note-' + personId()" data-testid="claim-form-note" formControlName="note" />
541	      <label [for]="'claim-form-corrects-' + personId()">Corrects claim no.</label>
542	      <input
543	        [id]="'claim-form-corrects-' + personId()"
544	        data-testid="claim-form-corrects"
545	        inputmode="numeric"
546	        formControlName="corrects"
547	      />
548	      <button type="submit" data-testid="claim-form-submit">
549	        {{ editingId() === null ? 'Add claim' : 'Save claim' }}
550	      </button>
551	      @if (editingId() !== null) {
552	        <button type="button" data-testid="claim-form-cancel" (click)="reset()">Cancel</button>
553	      }
554	    </form>
555	    @if (formError(); as e) {
556	      <p role="alert" data-testid="claim-form-error">{{ e }}</p>
557	    }
558	    @if (claims().length > 0) {
559	      <table data-testid="claim-list">
560	        <caption class="visually-hidden">Claims by {{ personName() }}</caption>
561	        <thead>
562	          <tr>
563	            <th scope="col"><span class="visually-hidden">Select</span></th>
564	            <th scope="col">No.</th>
565	            <th scope="col">Amount</th>
566	            <th scope="col">Date</th>
567	            <th scope="col">Note</th>
568	            <th scope="col">Period</th>
569	            <th scope="col">Due</th>
570	            <th scope="col">Due by</th>
571	            <th scope="col">Overdue</th>
572	            <th scope="col">Stated</th>
573	            <th scope="col">Status</th>
574	            <th scope="col">Opened by</th>
575	            <th scope="col">Corrects</th>
576	            <th scope="col"><span class="visually-hidden">Actions</span></th>
577	          </tr>
578	        </thead>
579	        <tbody>
580	          @for (c of claims(); track c.id) {
581	            <tr [attr.data-testid]="'claim-row-' + c.id">
582	              <td>
583	                <input
584	                  type="checkbox"
585	                  data-testid="claim-select"
586	                  [attr.aria-label]="'Select claim of ' + c.amount + ' on ' + c.date"
587	                  [checked]="selected().has(c.id)"
588	                  (change)="selectedChange.emit({ id: c.id, selected: $any($event.target).checked })"
589	                />
590	              </td>
591	              <td data-testid="claim-number">{{ c.number ?? '' }}</td>
592	              <td data-testid="claim-amount">{{ c.amount }}</td>
593	              <td data-testid="claim-date">{{ c.date }}</td>
594	              <td data-testid="claim-note">{{ c.note }}</td>
595	              <td data-testid="claim-period">{{ periodName(c) }}</td>
596	              <td data-testid="claim-due">{{ due(c) }}</td>
597	              <td data-testid="claim-due-by">{{ dueBy(c) }}</td>
598	              <td data-testid="claim-overdue">{{ overdue(c) ? 'yes' : 'no' }}</td>
599	              <td data-testid="claim-stated">{{ c.stated ? 'yes' : 'no' }}</td>
600	              <td data-testid="claim-status">{{ c.status }}</td>
601	              <td data-testid="claim-opened-by">{{ c.openedBy ?? '' }}</td>
602	              <td data-testid="claim-corrects">{{ c.corrects ?? '' }}</td>
603	              <td>
604	                <button
605	                  type="button"
606	                  data-testid="claim-edit"
607	                  [attr.aria-label]="'Edit claim of ' + c.amount + ' on ' + c.date"
608	                  (click)="edit(c)"
609	                >
610	                  Edit
611	                </button>
612	                @for (a of actions; track a.action) {
613	                  <button
614	                    type="button"
615	                    [attr.data-testid]="'claim-' + a.action"
616	                    [attr.aria-label]="a.label + ' claim of ' + c.amount + ' on ' + c.date"
617	                    (click)="changeStatus(c, a.action)"
618	                  >
619	                    {{ a.label }}
620	                  </button>
621	                }
622	                @if (claimError()?.id === c.id) {
623	                  <p role="alert" data-testid="claim-error">{{ claimError()?.message }}</p>
624	                }
625	              </td>
626	            </tr>
627	          }
628	        </tbody>
629	      </table>
630	    }
631	  `,
632	})
633	export class Claims {
634	  private readonly session = inject(Session);
635	  private readonly api = inject(ClaimsApi);
636	  private readonly floor = inject(SheetFloor);
637	  private readonly terms = inject(SheetTerms);
638	  private readonly latePct = inject(SheetLatePct);
639	  private readonly policyDate = inject(SheetPolicyDate);
640	  /** What a late charge goes by: the sheet's today, terms and late percent; and the policy date rounding goes
641	   * by. */
642	  private readonly late = computed<Lateness>(() => ({
643	    today: this.session.today(),
644	    terms: this.terms.value(),
645	    latePct: this.latePct.value(),
646	    policyDate: this.policyDate.value() ?? this.session.today(),
647	  }));
648	
649	  readonly personId = input.required<number>();
650	  readonly personName = input.required<string>();
651	  /** This person's claims, newest first. */
652	  readonly claims = input.required<Claim[]>();
653	  /** This person's dated grades, and the sheet's rates. */
654	  readonly grades = input.required<readonly GradeFrom[]>();
655	  readonly rates = input<readonly Rate[]>([]);
656	  /** The sheet's periods. */
657	  readonly periods = input<readonly Period[]>([]);
658	  /** The ids of the claims selected to act on together. */
659	  readonly selected = input<ReadonlySet<number>>(new Set());
660	  /** A claim was added or saved. */
661	  readonly saved = output<Claim>();
662	  /** A claim's select box was ticked or cleared. */
663	  readonly selectedChange = output<{ id: number; selected: boolean }>();
664	
665	  protected readonly actions: { action: ClaimAction; label: string }[] = [
666	    { action: 'open', label: 'Open' },
667	    { action: 'settle', label: 'Settle' },
668	    { action: 'void', label: 'Void' },
669	  ];
670	  protected readonly editingId = signal<number | null>(null);
671	  /** The error of the last action taken on a claim, shown on that claim's row. */
672	  protected readonly claimError = signal<{ id: number; message: string } | null>(null);
673	  protected readonly formError = signal<string | null>(null);
674	  /** Whether a submit is waiting on the server; another submit is ignored until it answers. */
675	  private submitting = false;
676	  protected readonly form = new FormGroup({
677	    amount: new FormControl('', { nonNullable: true }),
678	    date: new FormControl('', { nonNullable: true }),
679	    note: new FormControl('', { nonNullable: true }),
680	    corrects: new FormControl('', { nonNullable: true }),
681	  });
682	
683	  constructor() {
684	    this.form.valueChanges.subscribe(() => this.formError.set(null));
685	    // A new claim is dated the sheet's today unless another date is picked.
686	    effect(() => {
687	      const today = this.session.today() ?? '';
688	      untracked(() => {
689	        if (this.editingId() === null && !this.form.controls.date.dirty) {
690	          this.form.controls.date.setValue(today, { emitEvent: false });
691	        }
692	      });
693	    });
694	  }
695	
696	  /** A settled claim shows the due it was settled at; any other is due at the rate the grade its person has on
697	   * the claim's date has now in force on that date, and at least the sheet's floor, plus its late charge when
698	   * overdue. */
699	  protected due(claim: Claim): string {
700	    return claimDue(claim, this.rates(), gradeOn(this.grades(), claim.date), this.floor.value(), this.late(),
701	      roundsBy(claim, this.claims()));
702	  }
703	
704	  /** The claim's date plus the sheet's terms. */
705	  protected dueBy(claim: Claim): string {
706	    return dueBy(claim, this.terms.value());
707	  }
708	
709	  /** Whether the claim is OPEN and its due-by is before the sheet's today. */
710	  protected overdue(claim: Claim): boolean {
711	    return isOverdue(claim, this.terms.value(), this.session.today());
712	  }
713	
714	  /** The name of the period the claim's date falls in; empty when it falls in none. */
715	  protected periodName(claim: Claim): string {
716	    return periodOf(this.periods(), claim.date)?.name ?? '';
717	  }
718	
719	  protected changeStatus(claim: Claim, action: ClaimAction): void {
720	    this.claimError.set(null);
721	    const sheetId = this.session.sheetId();
722	    if (!sheetId) return;
723	    this.api.changeStatus(sheetId, claim.id, action).subscribe({
724	      next: (c) => {
725	        if (this.session.sheetId() === sheetId) this.saved.emit(c);
726	      },
727	      error: (e: HttpErrorResponse) =>
728	        this.claimError.set({
729	          id: claim.id,
730	          message:
731	            e.status === 403
732	              ? 'You opened that claim, so someone else must settle it.'
733	              : e.status === 422
734	              ? 'That claim\'s due is above the clerk limit, so only a steward can settle it.'
735	              : e.status === 423
736	              ? 'That claim is dated in a closed period.'
737	              : e.status === 409
738	              ? 'That claim\'s status does not allow that change.'
739	              : e.status === 404
740	                ? 'That claim is no longer on this sheet.'
741	                : 'Could not change that claim\'s status.',
742	        }),
743	    });
744	  }
745	
746	  protected edit(claim: Claim): void {
747	    this.claimError.set(null);
748	    if (claim.status !== 'DRAFT') {
749	      this.claimError.set({
750	        id: claim.id,
751	        message: 'Only a draft claim can be edited. To change it, void it and add a new one.',
752	      });
753	      return;
754	    }
755	    if (periodOf(this.periods(), claim.date)?.closed) {
756	      this.claimError.set({ id: claim.id, message: 'That claim is dated in a closed period.' });
757	      return;
758	    }
759	    this.editingId.set(claim.id);
760	    this.form.setValue(
761	      { amount: claim.amount, date: claim.date, note: claim.note, corrects: claim.corrects ?? '' },
762	      { emitEvent: false },
763	    );
764	    this.formError.set(null);
765	  }
766	
767	  protected reset(): void {
768	    this.editingId.set(null);
769	    this.form.reset(
770	      { amount: '', date: this.session.today() ?? '', note: '', corrects: '' },
771	      { emitEvent: false },
772	    );
773	    this.formError.set(null);
774	  }
775	
776	  protected submit(): void {
777	    if (this.submitting) return;
778	    this.formError.set(null);
779	    const sheetId = this.session.sheetId();
780	    if (!sheetId) {
781	      this.formError.set('Load a sheet first.');
782	      return;
783	    }
784	    const value = this.form.getRawValue();
785	    const amount = value.amount.trim();
786	    if (!AMOUNT.test(amount)) {
787	      this.formError.set('Type an amount with up to two decimals; a negative one is a correction.');
788	      return;
789	    }
790	    const corrects = value.corrects.trim();
791	    if (corrects !== '' && !NUMBER.test(corrects)) {
792	      this.formError.set('Type the number of the settled claim this corrects.');
793	      return;
794	    }
795	    const form = {
796	      amount,
797	      date: value.date || null,
798	      note: value.note.trim(),
799	      corrects: corrects === '' ? null : corrects,
800	    };
801	    const id = this.editingId();
802	    const request = id === null ? this.api.add(sheetId, this.personId(), form) : this.api.update(sheetId, id, form);
803	    this.submitting = true;
804	    request.subscribe({
805	      next: (c) => {
806	        this.submitting = false;
807	        if (this.session.sheetId() === sheetId) this.saved.emit(c);
808	        this.reset();
809	      },
810	      error: (e: HttpErrorResponse) => {
811	        this.submitting = false;
812	        this.formError.set(
813	          e.status === 400
814	            ? 'A negative amount is a correction: name the number of a settled claim of this person it corrects.'
815	            : e.status === 404
816	            ? 'That person or claim is no longer on this sheet.'
817	            : e.status === 422
818	              ? 'That claim is dated after its person is retired.'
819	              : e.status === 423
820	              ? 'That claim is dated in a closed period.'
821	              : e.status === 409
822	                ? 'Only a draft claim can be edited. To change it, void it and add a new one.'
823	                : 'Could not save that claim.',
824	        );
825	      },
826	    });
827	  }
828	}
