package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them: each person's claimed and due-total, and the sheet's
 * claimed-total and due-total. A change takes them before it alters anything and hands them back after, and
 * every figure it moved is written to the audit after the change's own lines. Called within the change's
 * transaction.
 */
@Service
public class RollupService {

    /** Shown in place of a due-total whose grade has no rate. */
    private static final String NO_RATE = "n/a";

    /** A person's figures, as the screen shows them. */
    public record Figures(String name, String claimed, String dueTotal) {}

    /** The sheet's figures at one moment: each person's by id, in the order they were added, and the totals. */
    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal) {}

    /** What a claim's late charge goes by: the sheet's today (none when there is no such sheet), its terms and
     * its late percent; and the date its rounding goes by, the policy date or else the sheet's today. */
    private record Lateness(LocalDate today, int terms, BigDecimal latePct, LocalDate policyDate) {

        static Lateness of(Sheet sheet) {
            return sheet == null ? new Lateness(null, 0, BigDecimal.ZERO, null)
                    : new Lateness(sheet.getToday(), sheet.getTerms(), sheet.getLatePct(), sheet.roundingDate());
        }

        /** How a claim's live figures round, by the date they go by: one before the policy date rounds half up,
         * one on or after it half to even. */
        RoundingMode rounding(LocalDate roundsBy) {
            return policyDate != null && roundsBy.isBefore(policyDate) ? RoundingMode.HALF_UP
                    : RoundingMode.HALF_EVEN;
        }
    }

    /** The days in each period an overdue claim gains its late percent for. */
    private static final int LATE_PERIOD_DAYS = 30;

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final Audit audit;

    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's figures now; none (an empty sheet's) when there is no such sheet. */
    public Snapshot snapshot(String sheetId) {
        Lateness late = latenessOf(sheetId);
        LocalDate today = late.today();
        BigDecimal floor = floorOf(sheetId);
        Map<Long, List<Claim>> byPerson = new LinkedHashMap<>();
        List<Claim> all = claims.findBySheetIdOrderByIdDesc(sheetId);
        for (Claim claim : all) {
            byPerson.computeIfAbsent(claim.getPersonId(), k -> new ArrayList<>()).add(claim);
        }
        Map<String, LocalDate> datesByNumber = datesByNumber(all);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
        Map<String, List<Rate>> byGrade = ratesByGrade(sheetId);
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            List<Claim> counted = byPerson.getOrDefault(person.getId(), List.of()).stream()
                    .filter(c -> counts(c, person)).toList();
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            boolean frozen = false;
            for (Claim claim : counted) {
                claimed = claimed.add(claim.getAmount().setScale(2));
                frozen |= keepsFigure(claim);
                BigDecimal figure = dueOf(claim, ratesOn(person, claim.getDate(), byGrade), floor, late,
                        roundsBy(claim, datesByNumber));
                if (figure != null) {
                    due = due.add(figure.setScale(2));
                }
            }
            // Like the screen: with no rate in force today and no claim keeping a figure, the due-total is n/a.
            boolean rated = rated(person, counted, today, byGrade);
            String personDue = rated || frozen ? due.toPlainString() : NO_RATE;
            claimedTotal = claimedTotal.add(claimed);
            if (rated || frozen) {
                dueTotal = dueTotal.add(due);
            }
            figures.put(person.getId(), new Figures(person.getName(), claimed.toPlainString(), personDue));
        }
        return new Snapshot(figures, claimedTotal.toPlainString(), dueTotal.toPlainString());
    }

    /** The due-total of the sheet's claims that count (a held person's OPEN ones do not) dated from and to, inclusive: the sum of their dues,
     * late charges included, n/a ones skipped. */
    public BigDecimal dueTotal(String sheetId, LocalDate from, LocalDate to) {
        BigDecimal floor = floorOf(sheetId);
        Lateness late = latenessOf(sheetId);
        Map<String, List<Rate>> byGrade = ratesByGrade(sheetId);
        Map<Long, Person> byId = new LinkedHashMap<>();
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            byId.put(person.getId(), person);
        }
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        List<Claim> all = claims.findBySheetIdOrderByIdDesc(sheetId);
        Map<String, LocalDate> datesByNumber = datesByNumber(all);
        for (Claim claim : all) {
            Person person = byId.get(claim.getPersonId());
            if (person == null || !counts(claim, person)
                    || claim.getDate().isBefore(from) || claim.getDate().isAfter(to)) {
                continue;
            }
            BigDecimal figure = dueOf(claim, ratesOn(person, claim.getDate(), byGrade), floor, late,
                    roundsBy(claim, datesByNumber));
            if (figure != null) {
                total = total.add(figure.setScale(2));
            }
        }
        return total;
    }

    /**
     * Write to the audit, once the change commits, one ROLLUP line for each person whose figures moved since
     * {@code before} (a person new since then counts as moved), in the order they were added, then a TOTALS
     * line when the sheet's totals moved.
     */
    public void recordChanges(String user, String sheetId, Snapshot before) {
        claims.flush();
        Snapshot after = snapshot(sheetId);
        String prefix = " sheet=" + sheetId + " by=" + user;
        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
            Figures now = e.getValue();
            Figures was = before.people().get(e.getKey());
            if (was != null && was.claimed().equals(now.claimed()) && was.dueTotal().equals(now.dueTotal())) {
                continue;
            }
            audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name() + " claimed=" + now.claimed()
                    + " due-total=" + now.dueTotal());
        }
        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
                || !Objects.equals(before.dueTotal(), after.dueTotal())) {
            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + after.claimedTotal()
                    + " due-total=" + after.dueTotal());
        }
    }

    /** The figure a claim has now: what it was settled at, else what its person's last statement bound it to,
     * else what is due at the rate of the grade its person has on its date, raised to the sheet's floor; none
     * when that is n/a. */
    public BigDecimal figureOf(Claim claim, Person person) {
        return figureOf(claim, gradeRates(claim, person), floorOf(claim.getSheetId()),
                latenessOf(claim.getSheetId()).rounding(roundsBy(claim)));
    }

    /** What is due on a claim now: its figure, plus the late charge an overdue claim has on it; none when the
     * figure is n/a. A settled claim's due is the figure it was settled at, the charge it had then frozen in. */
    public BigDecimal dueOf(Claim claim, Person person) {
        return dueOf(claim, gradeRates(claim, person), floorOf(claim.getSheetId()), latenessOf(claim.getSheetId()),
                roundsBy(claim));
    }

    /** The date a claim's rounding goes by: a correction's is the date of the claim it corrects, any other's its
     * own. */
    private LocalDate roundsBy(Claim claim) {
        return claim.getCorrects() == null ? claim.getDate()
                : roundsBy(claim, datesByNumber(claims.findBySheetIdAndPersonId(claim.getSheetId(),
                        claim.getPersonId())));
    }

    private static LocalDate roundsBy(Claim claim, Map<String, LocalDate> datesByNumber) {
        return claim.getCorrects() == null ? claim.getDate()
                : datesByNumber.getOrDefault(claim.getCorrects(), claim.getDate());
    }

    /** The dates of the claims given that have a number, by number. */
    private static Map<String, LocalDate> datesByNumber(List<Claim> given) {
        Map<String, LocalDate> by = new HashMap<>();
        for (Claim claim : given) {
            if (claim.getNumber() != null) {
                by.put(claim.getNumber(), claim.getDate());
            }
        }
        return by;
    }

    /**
     * Whether a person's due-total has a rate to go by on the sheet's today: the grade they have in force today,
     * or one they had on the date of a claim of theirs that counts, has a rate in force today.
     */
    public boolean rated(Person person, List<Claim> counted, LocalDate today) {
        return rated(person, counted, today, ratesByGrade(person.getSheetId()));
    }

    private static boolean rated(Person person, List<Claim> counted, LocalDate today,
            Map<String, List<Rate>> byGrade) {
        if (today == null) {
            return false;
        }
        Set<String> grades = new HashSet<>();
        grades.add(person.gradeOn(today));
        for (Claim claim : counted) {
            grades.add(person.gradeOn(claim.getDate()));
        }
        return grades.stream().anyMatch(g -> Rate.inForce(byGrade.getOrDefault(g, List.of()), today).isPresent());
    }

    /** The rates of the grade the claim's person has on the claim's date. */
    private List<Rate> gradeRates(Claim claim, Person person) {
        return rates.findBySheetIdAndGrade(claim.getSheetId(), person.gradeOn(claim.getDate()));
    }

    /** The rates of the grade a person has on a date. */
    private static List<Rate> ratesOn(Person person, LocalDate date, Map<String, List<Rate>> byGrade) {
        return byGrade.getOrDefault(person.gradeOn(date), List.of());
    }

    /** The sheet's rates by grade. */
    private Map<String, List<Rate>> ratesByGrade(String sheetId) {
        Map<String, List<Rate>> by = new HashMap<>();
        for (Rate rate : rates.findBySheetId(sheetId)) {
            by.computeIfAbsent(rate.getGrade(), k -> new ArrayList<>()).add(rate);
        }
        return by;
    }

    private static BigDecimal dueOf(Claim claim, List<Rate> gradeRates, BigDecimal floor, Lateness late,
            LocalDate roundsBy) {
        RoundingMode rounding = late.rounding(roundsBy);
        BigDecimal figure = figureOf(claim, gradeRates, floor, rounding);
        return figure == null ? null : figure.add(lateCharge(claim, figure, late, rounding));
    }

    /**
     * The late charge on a claim: the late percent of its figure for every full 30 days it is overdue (OPEN, and
     * its due-by, its date plus the terms, before the sheet's today), rounded to two decimals as the claim rounds.
     * A statement never binds it: it follows the sheet's today. A correction has none.
     */
    private static BigDecimal lateCharge(Claim claim, BigDecimal figure, Lateness late, RoundingMode rounding) {
        if (claim.getStatus() != ClaimStatus.OPEN || late.today() == null || claim.isCorrection()) {
            return BigDecimal.ZERO.setScale(2);
        }
        long overdueDays = ChronoUnit.DAYS.between(claim.getDate().plusDays(late.terms()), late.today());
        long periods = overdueDays > 0 ? overdueDays / LATE_PERIOD_DAYS : 0;
        return figure.multiply(late.latePct()).multiply(BigDecimal.valueOf(periods))
                .divide(BigDecimal.valueOf(100), 2, rounding);
    }

    private static BigDecimal figureOf(Claim claim, List<Rate> gradeRates, BigDecimal floor, RoundingMode rounding) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        return claim.isStated() ? claim.getStatedDue() : liveDueOf(claim, gradeRates, floor, rounding);
    }

    /** What is due on a claim at the rate its grade has in force on the claim's date, rounded to two decimals as
     * the claim rounds, and at least the floor (a correction has no floor); none when no rate of the grade applies
     * then. */
    private static BigDecimal liveDueOf(Claim claim, List<Rate> gradeRates, BigDecimal floor, RoundingMode rounding) {
        BigDecimal amount = claim.getAmount();
        return Rate.inForce(gradeRates, claim.getDate())
                .map(r -> amount.multiply(r.getRate()).divide(BigDecimal.valueOf(100), 2, rounding))
                .map(due -> claim.isCorrection() ? due : due.max(floor.setScale(2)))
                .orElse(null);
    }

    private Lateness latenessOf(String sheetId) {
        return Lateness.of(sheets.findById(sheetId).orElse(null));
    }

    /** The sheet's floor; 1.00, the one a sheet starts with, when there is no such sheet. */
    private BigDecimal floorOf(String sheetId) {
        return sheets.findById(sheetId).map(s -> s.getFloor()).orElse(new BigDecimal("1.00"));
    }

    /** Whether a claim keeps a figure whatever the rates: settled at one, or bound to one (not n/a) by a
     * statement. */
    public static boolean keepsFigure(Claim claim) {
        return claim.getSettledDue() != null || (claim.isStated() && claim.getStatedDue() != null);
    }

    /** Only OPEN and SETTLED claims count toward what is claimed and due; a held person's OPEN ones do not. */
    private static boolean counts(Claim claim, Person person) {
        return (claim.getStatus() == ClaimStatus.OPEN && !person.isHeld())
                || claim.getStatus() == ClaimStatus.SETTLED;
    }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { Session } from '../../core/session';
import { Grade } from '../people/people-api';
import { NO_RATE, Rate, dueOf, floored, fromHundredths, hundredths, rateOn } from '../rates/rates-api';

export interface Claim {
  id: number;
  personId: number;
  /** With two decimals, e.g. "10.00". */
  amount: string;
  /** yyyy-mm-dd */
  date: string;
  note: string;
  status: ClaimStatus;
  /** The sheet's number for the claim, given when it is opened; null while a draft or once voided. */
  number: string | null;
  /** What was due when the claim was settled, with two decimals; null while it is live (not settled, or
   * settled when its grade had no rate). */
  due: string | null;
  /** Who opened the claim; null while it is a draft. */
  openedBy: string | null;
  /** Whether the claim is bound to the figure it had at its person's last statement. */
  stated: boolean;
  /** That bound figure, with two decimals; null when it was n/a or the claim is not bound. */
  statedDue: string | null;
  /** For a correction (a negative amount), the number of the settled claim it corrects; null otherwise. */
  corrects: string | null;
}

/** Whether a claim is a correction: its amount is negative. */
export function isCorrection(claim: Claim): boolean {
  return claim.amount.startsWith('-');
}

/** A claim starts as DRAFT, is opened and then settled; a DRAFT or OPEN claim can be voided. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';

/** The status changes a person can ask for on a claim. */
export type ClaimAction = 'open' | 'settle' | 'void';

/** Only OPEN and SETTLED claims count toward what is claimed and due. */
export function counts(claim: Claim): boolean {
  return claim.status === 'OPEN' || claim.status === 'SETTLED';
}

/** What a claim's late charge goes by: the sheet's today, its terms and its late percent; and the policy date
 * its rounding goes by, the sheet's today when there is none. */
export interface Lateness {
  today: string | null;
  terms: number;
  /** With two decimals, e.g. "10.00". */
  latePct: string;
  policyDate: string | null;
}

/** The date a claim's rounding goes by: a correction's is the date of the claim of its person's (`claims`) it
 * corrects, any other's its own. */
export function roundsBy(claim: Claim, claims: readonly Claim[]): string {
  if (claim.corrects === null) return claim.date;
  return claims.find((c) => c.number === claim.corrects)?.date ?? claim.date;
}

/** Whether a claim's live figures round half up: the date they go by is before the policy date. Otherwise
 * they round half to even. */
function roundsHalfUp(date: string, late: Lateness): boolean {
  return late.policyDate !== null && date < late.policyDate;
}

/** The days in each period an overdue claim gains the late percent for. */
const LATE_PERIOD_DAYS = 30;

/** A settled claim's due is the figure it was settled at (its late charge frozen in); a claim bound by its
 * person's last statement has the figure it was bound to; any other has the figure due at the rate `grade`, the
 * one its person has on the claim's date, has now in force on that date, and at least the sheet's floor (n/a
 * when there is no rate). An overdue claim's due adds its late charge to its figure. Live figures round by the
 * date `roundsBy` (see {@link roundsBy}). */
export function claimDue(
  claim: Claim,
  rates: readonly Rate[],
  grade: Grade | undefined,
  floor: string,
  late: Lateness,
  roundsBy: string = claim.date,
): string {
  if (claim.due !== null) return claim.due;
  const halfUp = roundsHalfUp(roundsBy, late);
  const figure = claim.stated
    ? (claim.statedDue ?? NO_RATE)
    : correctionFloored(claim, dueOf(claim.amount, grade && rateOn(rates, grade, claim.date), halfUp), floor);
  if (figure === NO_RATE) return figure;
  return sumAmounts([figure, lateCharge(claim, figure, late, halfUp)]);
}

/** A due raised to the sheet's floor, except a correction's, which has no floor. */
function correctionFloored(claim: Claim, due: string, floor: string): string {
  return isCorrection(claim) ? due : floored(due, floor);
}

/** The late charge on an overdue claim: the late percent of its figure for every full 30 days it is overdue,
 * rounded like a due; never bound by a statement, it follows the sheet's today. A correction has none. */
function lateCharge(claim: Claim, figure: string, late: Lateness, halfUp: boolean): string {
  if (isCorrection(claim) || !isOverdue(claim, late.terms, late.today) || late.today === null) return '0.00';
  const days = (Date.parse(late.today) - Date.parse(dueBy(claim, late.terms))) / 86_400_000;
  const periods = Math.floor(days / LATE_PERIOD_DAYS);
  return dueOf(figure, timesPct(late.latePct, periods), halfUp);
}

/** A percent with two decimals times a whole number, with two decimals. */
function timesPct(pct: string, times: number): string {
  const [whole, frac = ''] = pct.split('.');
  const hundredths = (BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0'))) * BigInt(times);
  return `${hundredths / 100n}.${String(hundredths % 100n).padStart(2, '0')}`;
}

/** Whether a claim keeps a figure whatever the rates: settled at one, or bound to one (not n/a) by a
 * statement. */
export function keepsFigure(claim: Claim): boolean {
  return claim.due !== null || claim.statedDue !== null;
}

/** The date a claim is due by: its date plus the sheet's terms in days (yyyy-mm-dd). */
export function dueBy(claim: Claim, terms: number): string {
  const [y, m, d] = claim.date.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + terms)).toISOString().slice(0, 10);
}

/** Whether a claim is overdue: it is OPEN and its due-by is before the sheet's today. */
export function isOverdue(claim: Claim, terms: number, today: string | null): boolean {
  return claim.status === 'OPEN' && today !== null && dueBy(claim, terms) < today;
}

export interface ClaimForm {
  amount: string;
  /** Null for the sheet's today. */
  date: string | null;
  note: string;
  /** The number of the settled claim a correction corrects; null when none is named. */
  corrects: string | null;
}

/** What opening claims together did: how many were opened and refused, and the opened claims. */
export interface OpenedAll {
  opened: number;
  refused: number;
  claims: Claim[];
}

/** The sum of claim amounts with two decimals, added up in cents so no rounding creeps in. */
export function sumAmounts(amounts: string[]): string {
  return fromHundredths(amounts.reduce((sum, a) => sum + hundredths(a), 0n));
}

// The claims people make on the active sheet, read and changed through the server.
@Injectable({ providedIn: 'root' })
export class ClaimsApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  list(sheetId: string): Observable<Claim[]> {
    return this.http.get<Claim[]>(`${this.url(sheetId)}/claims`, { headers: this.headers() });
  }

  add(sheetId: string, personId: number, form: ClaimForm): Observable<Claim> {
    return this.http.post<Claim>(`${this.url(sheetId)}/people/${personId}/claims`, form, {
      headers: this.headers(),
    });
  }

  update(sheetId: string, id: number, form: ClaimForm): Observable<Claim> {
    return this.http.put<Claim>(`${this.url(sheetId)}/claims/${id}`, form, { headers: this.headers() });
  }

  changeStatus(sheetId: string, id: number, action: ClaimAction): Observable<Claim> {
    return this.http.post<Claim>(`${this.url(sheetId)}/claims/${id}/${action}`, null, { headers: this.headers() });
  }

  /** Open the claims together; each that cannot be opened is refused and left as it is. */
  openAll(sheetId: string, ids: number[]): Observable<OpenedAll> {
    return this.http.post<OpenedAll>(`${this.url(sheetId)}/claims/open`, { ids }, { headers: this.headers() });
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}`;
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }
}
